package alphametics

import (
	"errors"
	"strings"
)

// Solve parses an alphametics puzzle of the form
// "WORD + WORD + ... == WORD" and returns the letter-to-digit
// substitution that makes the equation valid, or an error if no
// solution exists.
func Solve(puzzle string) (map[string]int, error) {
	eqParts := strings.Split(puzzle, "==")
	if len(eqParts) != 2 {
		return nil, errors.New("puzzle must contain exactly one == operator")
	}
	addendWords := splitWords(eqParts[0], true)
	resultWords := splitWords(eqParts[1], false)
	if len(addendWords) == 0 || len(resultWords) != 1 {
		return nil, errors.New("invalid puzzle format")
	}

	// Collect unique letters (in order of first appearance) and
	// mark letters that lead a multi-digit word.
	index := map[byte]int{}
	var letters []byte
	letterOf := func(b byte) int {
		if i, ok := index[b]; ok {
			return i
		}
		i := len(letters)
		index[b] = i
		letters = append(letters, b)
		return i
	}
	allWords := append(append([]string{}, addendWords...), resultWords[0])
	n := 0
	// First pass: assign indices.
	for _, w := range allWords {
		for i := 0; i < len(w); i++ {
			letterOf(w[i])
		}
		n = len(letters)
	}
	if n > 10 {
		return nil, errors.New("puzzle has more than 10 distinct letters")
	}
	leading := make([]bool, n)
	for _, w := range allWords {
		if len(w) > 1 {
			leading[index[w[0]]] = true
		}
	}

	// Build columns, least significant first. Each column holds the
	// letter indices contributed by the addends and the result letter
	// for that column (-1 if the result has no digit there).
	cols := 0
	for _, w := range allWords {
		if len(w) > cols {
			cols = len(w)
		}
	}
	type column struct {
		add []int
		res int
	}
	colData := make([]column, cols)
	for _, w := range addendWords {
		for i := 0; i < len(w); i++ {
			c := len(w) - 1 - i
			colData[c].add = append(colData[c].add, index[w[i]])
		}
	}
	res := resultWords[0]
	for c := range colData {
		colData[c].res = -1
	}
	for i := 0; i < len(res); i++ {
		c := len(res) - 1 - i
		colData[c].res = index[res[i]]
	}

	val := make([]int, n)
	for i := range val {
		val[i] = -1
	}
	var used [10]bool

	// assign fills in the addend letters of column col starting at
	// row, then checks the resulting digit against the result letter.
	var assign func(col, row, sum int) bool
	var solveCol func(col, carry int) bool

	assign = func(col, row, sum int) bool {
		if row == len(colData[col].add) {
			return solveCol2(col, sum)
		}
		li := colData[col].add[row]
		if v := val[li]; v >= 0 {
			return assign(col, row+1, sum+v)
		}
		for d := 0; d <= 9; d++ {
			if used[d] || (leading[li] && d == 0) {
				continue
			}
			val[li] = d
			used[d] = true
			if assign(col, row+1, sum+d) {
				return true
			}
			val[li] = -1
			used[d] = false
		}
		return false
	}

	solveCol2 := func(col, sum int) bool {
		total := sum
		digit := total % 10
		carry := total / 10
		li := colData[col].res
		if li < 0 {
			// No result digit here; the column must vanish entirely.
			if digit != 0 {
				return false
			}
			return solveCol(col+1, carry)
		}
		if v := val[li]; v >= 0 {
			if v != digit {
				return false
			}
			return solveCol(col+1, carry)
		}
		if used[digit] || (leading[li] && digit == 0) {
			return false
		}
		val[li] = digit
		used[digit] = true
		if solveCol(col+1, carry) {
			return true
		}
		val[li] = -1
		used[digit] = false
		return false
	}

	solveCol = func(col, carry int) bool {
		if col == cols {
			return carry == 0
		}
		return assign(col, 0, carry)
	}

	if !solveCol(0, 0) {
		return nil, errors.New("no solution")
	}
	solution := make(map[string]int, n)
	for i, l := range letters {
		solution[string(l)] = val[i]
	}
	return solution, nil
}

// splitWords splits the given puzzle fragment into alphabetic words,
// allowing '+' as a separator when allowPlus is true.
func splitWords(s string, allowPlus bool) []string {
	isSeparator := func(r rune) bool {
		if r == '+' {
			return allowPlus
		}
		return r == ' ' || r == '\t' || r == '\n' || r == '\r'
	}
	var words []string
	for _, w := range strings.FieldsFunc(s, isSeparator) {
		for i := 0; i < len(w); i++ {
			c := w[i]
			if (c < 'A' || c > 'Z') && (c < 'a' || c > 'z') {
				return nil // invalid character in a word
			}
		}
		words = append(words, strings.ToUpper(w))
	}
	return words
}

